from PIL import Image, ImageOps
im = Image.open('radiograph.jpg').convert('L')
crops = {
 'ant_upper': (600, 480, 1500, 800),
 'ant_lower': (600, 720, 1500, 1080),
}
for name,box in crops.items():
    c = im.crop(box)
    c = ImageOps.autocontrast(c, cutoff=0)
    c = c.resize((int(c.width*2.0), int(c.height*2.0)))
    c.save(f'{name}.png'); print(name, box, c.size)
"", "description": "Crop anterior regions"}

